Json encode_object(const ChatInviteLink& value, Request* request) {
    Json json = Json::object();
    detail::write_field(json, "invite_link", value.invite_link, request);
    detail::write_field(json, "creator", value.creator, request);
    detail::write_field(json, "creates_join_request", value.creates_join_request, request);
    detail::write_field(json, "is_primary", value.is_primary, request);
    detail::write_field(json, "is_revoked", value.is_revoked, request);
    detail::write_field(json, "name", value.name, request);
    detail::write_field(json, "expire_date", value.expire_date, request);
    detail::write_field(json, "member_limit", value.member_limit, request);
    detail::write_field(
        json, "pending_join_request_count", value.pending_join_request_count, request);
    detail::write_field(json, "subscription_period", value.subscription_period, request);
    detail::write_field(json, "subscription_price", value.subscription_price, request);
    return json;
}

